import{_ as l,o as i,c as a,a2 as r}from"./chunks/framework.QCr1ZR1X.js";const b=JSON.parse('{"title":"第2章 工业互联网基础（教师用书）","description":"","frontmatter":{},"headers":[],"relativePath":"teacher/ch2/教师用书-第2章-工业互联网基础.md","filePath":"teacher/ch2/教师用书-第2章-工业互联网基础.md","lastUpdated":1786967935000}'),o={name:"teacher/ch2/教师用书-第2章-工业互联网基础.md"};function d(e,t,h,n,s,u){return i(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="第2章-工业互联网基础-教师用书" tabindex="-1">第2章 工业互联网基础（教师用书） <a class="header-anchor" href="#第2章-工业互联网基础-教师用书" aria-label="Permalink to &quot;第2章 工业互联网基础（教师用书）&quot;">​</a></h1><h2 id="本章概述" tabindex="-1">本章概述 <a class="header-anchor" href="#本章概述" aria-label="Permalink to &quot;本章概述&quot;">​</a></h2><p>本章是全书承上启下的关键章节。上一章学生掌握了互联网基础，这一章从消费互联网转向工业互联网，建立工业互联网的概念体系和基本工具使用能力。</p><h3 id="本章定位" tabindex="-1">本章定位 <a class="header-anchor" href="#本章定位" aria-label="Permalink to &quot;本章定位&quot;">​</a></h3><ul><li><strong>知识层面</strong>：建立工业互联网的完整概念体系（起源、定义、架构、要素）</li><li><strong>技能层面</strong>：掌握Linux环境下SSH远程管理和基本命令，体验云服务器</li><li><strong>素养层面</strong>：建立数据闭环思维，理解制造强国战略，树立网络安全法治意识</li></ul><h3 id="学情分析" tabindex="-1">学情分析 <a class="header-anchor" href="#学情分析" aria-label="Permalink to &quot;学情分析&quot;">​</a></h3><ul><li><strong>优势</strong>：学生有互联网使用经验，容易理解消费互联网的概念</li><li><strong>难点</strong>：工业场景陌生，对架构的理解容易流于表面</li><li><strong>教学策略</strong>：用大量真实案例（黑灯工厂、三一挖掘机、劳斯莱斯）替代抽象概念</li></ul><hr><h2 id="教学目标" tabindex="-1">教学目标 <a class="header-anchor" href="#教学目标" aria-label="Permalink to &quot;教学目标&quot;">​</a></h2><h3 id="知识目标" tabindex="-1">知识目标 <a class="header-anchor" href="#知识目标" aria-label="Permalink to &quot;知识目标&quot;">​</a></h3><ol><li>理解工业互联网的定义、起源（德国工业4.0、美国工业互联网、中国制造2025）</li><li>掌握IIRA四层参考架构（边缘层、平台层、应用层、业务层）</li><li>了解工业互联网五大构成要素和产业生态中的四类角色</li><li>理解&quot;数据闭环&quot;在工业互联网中的核心作用</li></ol><h3 id="技能目标" tabindex="-1">技能目标 <a class="header-anchor" href="#技能目标" aria-label="Permalink to &quot;技能目标&quot;">​</a></h3><ol><li>能够在Ubuntu上安装和启动SSH服务</li><li>能够从Windows通过SSH远程登录Linux服务器</li><li>掌握9个Linux基本命令（pwd、ls、cd、mkdir、touch、nano、cat、tree、rm）</li><li>能够在云平台创建ECS实例、配置安全组、远程登录</li></ol><h3 id="素养目标" tabindex="-1">素养目标 <a class="header-anchor" href="#素养目标" aria-label="Permalink to &quot;素养目标&quot;">​</a></h3><ol><li><strong>分层思维</strong>：理解复杂系统通过分层实现解耦和复用</li><li><strong>数据闭环思维</strong>：建立&quot;感知-传输-分析-决策-执行-反馈&quot;的完整闭环意识</li><li><strong>法治意识</strong>：遵守网络安全法律法规，树立工业安全意识</li><li><strong>岗位意识</strong>：了解工业互联网工程技术人员的职业标准和能力要求</li></ol><hr><h2 id="课时分配与教学安排" tabindex="-1">课时分配与教学安排 <a class="header-anchor" href="#课时分配与教学安排" aria-label="Permalink to &quot;课时分配与教学安排&quot;">​</a></h2><table tabindex="0"><thead><tr><th>课次</th><th>课时</th><th>内容</th><th>教学类型</th><th>重点/难点</th><th>教学建议</th></tr></thead><tbody><tr><td>第1次</td><td>2h</td><td>2.1 从黑灯工厂看工业互联网本质（起源+定义+与消费互联网对比）</td><td>理论</td><td><strong>重点</strong>：三国工业互联网战略对比<br><strong>难点</strong>：工业互联网与消费互联网的本质区别</td><td>用大量案例、视频让学生直观感受黑灯工厂</td></tr><tr><td>第2次</td><td>2h</td><td>2.2 实践：SSH远程管理与Linux命令入门</td><td>理实混合</td><td><strong>重点</strong>：SSH远程登录<br><strong>难点</strong>：Linux文件系统和命令理解</td><td>边讲边练，确保每个学生都能成功登录</td></tr><tr><td>第3次</td><td>2h</td><td>2.3 IIRA四层架构与工业互联网构成要素</td><td>理论</td><td><strong>重点</strong>：数据在四层之间的流动<br><strong>难点</strong>：数字孪生概念理解</td><td>用预测性维护、大规模定制两个场景贯穿</td></tr><tr><td>第4次</td><td>2h</td><td>2.4 实践：云服务器注册与远程登录</td><td>实践</td><td><strong>重点</strong>：云服务器创建与安全组配置<br><strong>难点</strong>：理解云服务器的本质</td><td>鼓励学生用学生认证领取免费额度</td></tr></tbody></table><hr><h2 id="各节教学实施建议" tabindex="-1">各节教学实施建议 <a class="header-anchor" href="#各节教学实施建议" aria-label="Permalink to &quot;各节教学实施建议&quot;">​</a></h2><h3 id="_2-1-从黑灯工厂看工业互联网本质" tabindex="-1">2.1 从黑灯工厂看工业互联网本质 <a class="header-anchor" href="#_2-1-从黑灯工厂看工业互联网本质" aria-label="Permalink to &quot;2.1 从黑灯工厂看工业互联网本质&quot;">​</a></h3><h4 id="教学导入-10分钟" tabindex="-1">教学导入（10分钟） <a class="header-anchor" href="#教学导入-10分钟" aria-label="Permalink to &quot;教学导入（10分钟）&quot;">​</a></h4><p><strong>互动提问</strong>：</p><ul><li>&quot;你见过自动化程度最高的工厂是什么样的？&quot;</li><li>&quot;工厂里的网络和我们家里的WiFi有什么不一样吗？&quot;</li></ul><p><strong>播放视频</strong>：小米亦庄智能工厂/特斯拉上海超级工厂视频（5分钟）</p><h4 id="黑灯工厂案例-15分钟" tabindex="-1">黑灯工厂案例（15分钟） <a class="header-anchor" href="#黑灯工厂案例-15分钟" aria-label="Permalink to &quot;黑灯工厂案例（15分钟）&quot;">​</a></h4><ul><li>详细讲解三个案例：小米智能工厂、特斯拉焊装车间、三一18号厂房</li><li><strong>关键提问</strong>：&quot;这些工厂关灯后怎么生产？&quot;引出&quot;数据&quot;的核心作用</li><li>用空调的闭环控制类比工业互联网的闭环</li></ul><h4 id="工业互联网起源-20分钟" tabindex="-1">工业互联网起源（20分钟） <a class="header-anchor" href="#工业互联网起源-20分钟" aria-label="Permalink to &quot;工业互联网起源（20分钟）&quot;">​</a></h4><table tabindex="0"><thead><tr><th>国家</th><th>战略</th><th>时间</th><th>侧重点</th><th>代表案例</th></tr></thead><tbody><tr><td>德国</td><td>工业4.0</td><td>2011</td><td>生产柔性、智能制造</td><td>西门子安贝格工厂</td></tr><tr><td>美国</td><td>工业互联网</td><td>2012</td><td>预测性维护、资产效能</td><td>GE航空发动机</td></tr><tr><td>中国</td><td>中国制造2025</td><td>2015/2017</td><td>两化融合、产业升级</td><td>三一重工</td></tr></tbody></table><p><strong>思政融入</strong>：</p><ul><li>从&quot;中国制造&quot;到&quot;中国智造&quot;的跨越</li><li>中国从跟跑到并跑再到领跑的机遇</li></ul><h4 id="四项关键技术成熟-15分钟" tabindex="-1">四项关键技术成熟（15分钟） <a class="header-anchor" href="#四项关键技术成熟-15分钟" aria-label="Permalink to &quot;四项关键技术成熟（15分钟）&quot;">​</a></h4><ul><li>传感技术：从昂贵到便宜</li><li>通信技术：从有线到5G、TSN</li><li>云计算：从自建机房到弹性扩容</li><li>AI与机器学习：从专家经验到自动学习</li></ul><h4 id="定义与对比-20分钟" tabindex="-1">定义与对比（20分钟） <a class="header-anchor" href="#定义与对比-20分钟" aria-label="Permalink to &quot;定义与对比（20分钟）&quot;">​</a></h4><ol><li>给出三个机构的定义（IIC、AII、学术界）</li><li><strong>关键对比表讲解</strong>：消费互联网 vs 工业互联网</li><li>两个震撼场景： <ul><li>刷抖音卡顿vs机械臂撞坏工件（延迟后果对比）</li><li>家用路由器vs工业路由器（工作环境对比）</li></ul></li></ol><h4 id="回顾反思-10分钟" tabindex="-1">回顾反思（10分钟） <a class="header-anchor" href="#回顾反思-10分钟" aria-label="Permalink to &quot;回顾反思（10分钟）&quot;">​</a></h4><ul><li>小组讨论3分钟，然后请2-3组分享</li><li>问题：&quot;你宿舍的路由器是工业互联网吗？&quot;</li></ul><hr><h3 id="_2-2-动手实践-ssh远程管理与linux命令入门" tabindex="-1">2.2 动手实践：SSH远程管理与Linux命令入门 <a class="header-anchor" href="#_2-2-动手实践-ssh远程管理与linux命令入门" aria-label="Permalink to &quot;2.2 动手实践：SSH远程管理与Linux命令入门&quot;">​</a></h3><h4 id="实践准备" tabindex="-1">实践准备 <a class="header-anchor" href="#实践准备" aria-label="Permalink to &quot;实践准备&quot;">​</a></h4><p><strong>课前检查</strong>：</p><ul><li>确保机房电脑可以安装VMware</li><li>提前克隆好Ubuntu虚拟机镜像，避免课上安装浪费时间</li><li>确保网络环境支持桥接模式（可选：提前准备好网络故障模拟场景）</li></ul><h4 id="教学流程" tabindex="-1">教学流程 <a class="header-anchor" href="#教学流程" aria-label="Permalink to &quot;教学流程&quot;">​</a></h4><p><strong>环节1：SSH服务安装与启动（20分钟）</strong></p><ol><li>在VMware窗口直接登录Ubuntu</li><li>演示apt update、apt install openssh-server</li><li>演示systemctl status ssh查看状态</li><li>演示ip addr查看IP地址</li><li><strong>学生练习</strong>：每人完成这四个步骤，记录下自己的虚拟机IP</li></ol><p><strong>环节2：从Windows SSH登录（25分钟）</strong></p><ol><li>讲解SSH是什么（远程管理协议）</li><li>演示Windows终端执行ssh <a href="mailto:student@xxx.xxx.xxx.xxx" target="_blank" rel="noreferrer">student@xxx.xxx.xxx.xxx</a></li><li>讲解host key确认、密码输入（不显示字符是安全设计）</li><li><strong>学生练习</strong>：相互ping对方的虚拟机，相互SSH登录（如果环境允许）</li></ol><p><strong>环节3：Linux基本命令（40分钟）</strong> 建议教学节奏：</p><ul><li>pwd、ls、ls -l、ls -a（10分钟，边讲边练）</li><li>cd /home、cd ~、cd ..（10分钟）</li><li>mkdir、touch、echo、cat、nano（15分钟，nano重点讲解）</li><li>tree、cp、mv、rm（5分钟，强调rm不可恢复）</li></ul><p><strong>关键点提醒</strong>：</p><ul><li>Linux路径分隔符是/不是\\</li><li>区分大小写</li><li>rm删除不可恢复（提醒学生谨慎操作）</li></ul><p><strong>环节4：软件包管理apt（15分钟）</strong></p><ol><li>讲解apt是&quot;应用商店&quot;</li><li>演示apt install curl</li><li>演示curl ifconfig.me、curl wttr.in（趣味演示，提高兴趣）</li><li><strong>学生练习</strong>：安装curl并试用</li></ol><h4 id="常见问题与解答" tabindex="-1">常见问题与解答 <a class="header-anchor" href="#常见问题与解答" aria-label="Permalink to &quot;常见问题与解答&quot;">​</a></h4><table tabindex="0"><thead><tr><th>学生问题</th><th>解答要点</th></tr></thead><tbody><tr><td>SSH连接被拒绝</td><td>检查SSH服务是否启动（systemctl status ssh），检查IP地址是否正确</td></tr><tr><td>桥接模式无法获取IP</td><td>尝试NAT模式（但同学之间无法互访），或检查网络限制</td></tr><tr><td>rm删错了文件怎么办</td><td>抱歉，Linux下rm删除不可恢复，操作前请三思</td></tr><tr><td>nano编辑器怎么用</td><td>^X是Ctrl+X，然后Y保存，回车确认文件名</td></tr></tbody></table><h4 id="评价设计" tabindex="-1">评价设计 <a class="header-anchor" href="#评价设计" aria-label="Permalink to &quot;评价设计&quot;">​</a></h4><ul><li>过程性评价：检查每个学生成功完成SSH登录</li><li>实践任务评价表：学生自评+互评+师评</li></ul><hr><h3 id="_2-3-iira四层参考架构与工业互联网构成要素" tabindex="-1">2.3 IIRA四层参考架构与工业互联网构成要素 <a class="header-anchor" href="#_2-3-iira四层参考架构与工业互联网构成要素" aria-label="Permalink to &quot;2.3 IIRA四层参考架构与工业互联网构成要素&quot;">​</a></h3><h4 id="教学导入-5分钟" tabindex="-1">教学导入（5分钟） <a class="header-anchor" href="#教学导入-5分钟" aria-label="Permalink to &quot;教学导入（5分钟）&quot;">​</a></h4><p><strong>提问回顾</strong>：&quot;上一章讲的TCP/IP是四层，这一章的IIRA也是四层，它们有什么关系吗？&quot; <strong>回答引导</strong>：TCP/IP解决网络通信，IIRA解决工业系统架构</p><h4 id="iira四层参考架构-30分钟" tabindex="-1">IIRA四层参考架构（30分钟） <a class="header-anchor" href="#iira四层参考架构-30分钟" aria-label="Permalink to &quot;IIRA四层参考架构（30分钟）&quot;">​</a></h4><table tabindex="0"><thead><tr><th>层级</th><th>功能</th><th>类比</th><th>对应工业元素</th></tr></thead><tbody><tr><td>边缘层</td><td>数据采集、指令执行</td><td>眼睛、手脚</td><td>传感器、PLC、机器人</td></tr><tr><td>平台层</td><td>数据存储、分析、AI</td><td>大脑</td><td>云平台、大数据引擎</td></tr><tr><td>应用层</td><td>呈现给人使用</td><td>界面</td><td>MES、预测性维护APP</td></tr><tr><td>业务层</td><td>经营决策</td><td>大脑皮层</td><td>ERP、供应链管理</td></tr></tbody></table><p><strong>讲解策略</strong>：</p><ul><li>每个层级用一句话、一个类比、一个工业元素讲清楚</li><li>建筑蓝图类比贯穿始终</li></ul><h4 id="数据流动-30分钟" tabindex="-1">数据流动（30分钟） <a class="header-anchor" href="#数据流动-30分钟" aria-label="Permalink to &quot;数据流动（30分钟）&quot;">​</a></h4><p><strong>两个核心场景详细讲解</strong>：</p><p><strong>场景1：预测性维护</strong></p><ul><li>边缘层：振动传感器采样</li><li>平台层：AI模型分析振动特征</li><li>应用层：手机APP弹出预警</li><li>业务层：计入OEE报表</li></ul><p><strong>场景2：大规模定制</strong></p><ul><li>业务层：用户在线下单</li><li>平台层：订单管理、排产引擎</li><li>应用层：工位显示屏显示参数</li><li>边缘层：裁床、缝纫机执行</li></ul><p><strong>可视化建议</strong>：</p><ul><li>在黑板上画数据流动箭头，或用PPT动画展示</li><li>请学生上台指出每个环节属于哪一层</li></ul><h4 id="五大构成要素-20分钟" tabindex="-1">五大构成要素（20分钟） <a class="header-anchor" href="#五大构成要素-20分钟" aria-label="Permalink to &quot;五大构成要素（20分钟）&quot;">​</a></h4><ol><li>感知层</li><li>网络层</li><li>平台层</li><li>应用层</li><li>安全层（贯穿其他四层）</li></ol><p><strong>思政融入</strong>：</p><ul><li>《网络安全法》第二十一条：网络安全等级保护制度</li><li>工业安全的重要性（震网病毒案例回顾）</li></ul><h4 id="产业生态与商业模式-15分钟" tabindex="-1">产业生态与商业模式（15分钟） <a class="header-anchor" href="#产业生态与商业模式-15分钟" aria-label="Permalink to &quot;产业生态与商业模式（15分钟）&quot;">​</a></h4><p>四类角色：设备商、平台商、集成商、最终用户 三个商业模式案例：</p><ol><li>劳斯莱斯：卖推力不卖发动机</li><li>阿特拉斯科普柯：卖压缩空气不卖空压机</li><li>三一重工：卖设备可用时间，挖掘机指数</li></ol><h4 id="回顾反思-10分钟-1" tabindex="-1">回顾反思（10分钟） <a class="header-anchor" href="#回顾反思-10分钟-1" aria-label="Permalink to &quot;回顾反思（10分钟）&quot;">​</a></h4><p>小组讨论：&quot;你未来最想成为四类角色中的哪一类？为什么？&quot;</p><hr><h3 id="_2-4-动手实践-云服务器注册与远程登录" tabindex="-1">2.4 动手实践：云服务器注册与远程登录 <a class="header-anchor" href="#_2-4-动手实践-云服务器注册与远程登录" aria-label="Permalink to &quot;2.4 动手实践：云服务器注册与远程登录&quot;">​</a></h3><h4 id="实践准备-1" tabindex="-1">实践准备 <a class="header-anchor" href="#实践准备-1" aria-label="Permalink to &quot;实践准备&quot;">​</a></h4><ul><li>提醒学生提前准备身份证（实名认证需要）</li><li>提前收集主流云平台的学生认证信息（阿里云、腾讯云、华为云）</li></ul><h4 id="教学流程-1" tabindex="-1">教学流程 <a class="header-anchor" href="#教学流程-1" aria-label="Permalink to &quot;教学流程&quot;">​</a></h4><p><strong>环节1：云平台注册与ECS创建（25分钟）</strong></p><ol><li>演示注册阿里云账号（手机注册）</li><li>演示实名认证（可提前完成）</li><li>演示创建ECS实例的关键配置项 <ul><li>地域：离学生最近的</li><li>镜像：Ubuntu 22.04</li><li>规格：1核1GB</li><li>带宽：分配公网IP</li></ul></li><li><strong>学生练习</strong>：注册账号，创建ECS（如果条件限制，可分组完成）</li></ol><p><strong>环节2：安全组配置（20分钟）</strong></p><ol><li>讲解安全组是什么（&quot;云防火墙&quot;）</li><li>演示添加入方向规则，开放SSH端口22</li><li><strong>对比讲解</strong>：云安全组 vs Windows防火墙 vs 工业防火墙</li><li><strong>工业视角</strong>：真实生产环境不应该开放0.0.0.0/0，应限制IP</li></ol><p><strong>环节3：SSH登录云服务器（20分钟）</strong></p><ol><li>演示ssh root@公网IP</li><li>演示执行几个命令：timedatectl、curl wttr.in、curl ifconfig.me</li><li><strong>学生练习</strong>：登录自己的云服务器，执行几个命令</li></ol><p><strong>环节4：本地虚拟机vs云服务器对比（15分钟）</strong></p><table tabindex="0"><thead><tr><th>维度</th><th>本地虚拟机</th><th>云服务器</th></tr></thead><tbody><tr><td>位置</td><td>你电脑里</td><td>别人机房</td></tr><tr><td>关机</td><td>一起关</td><td>继续运行</td></tr><tr><td>访问</td><td>局域网</td><td>全球访问</td></tr><tr><td>费用</td><td>免费</td><td>按需付费</td></tr></tbody></table><h4 id="常见问题与解答-1" tabindex="-1">常见问题与解答 <a class="header-anchor" href="#常见问题与解答-1" aria-label="Permalink to &quot;常见问题与解答&quot;">​</a></h4><table tabindex="0"><thead><tr><th>学生问题</th><th>解答要点</th></tr></thead><tbody><tr><td>学生认证怎么弄</td><td>各平台不同，一般需要学信网验证或学生证照片，鼓励课后自行完成</td></tr><tr><td>安全组配置后还连不上</td><td>等待1-2分钟规则生效，检查IP地址是否正确</td></tr><tr><td>云服务器太贵怎么办</td><td>用学生认证免费额度，实验后释放避免扣费</td></tr><tr><td>root密码忘了</td><td>在云控制台重置实例密码</td></tr></tbody></table><h4 id="评价设计-1" tabindex="-1">评价设计 <a class="header-anchor" href="#评价设计-1" aria-label="Permalink to &quot;评价设计&quot;">​</a></h4><ul><li>成功创建云服务器并远程登录（基础要求）</li><li>能说出本地与云端至少3个区别（进阶要求）</li></ul><hr><h2 id="本章总结与拓展" tabindex="-1">本章总结与拓展 <a class="header-anchor" href="#本章总结与拓展" aria-label="Permalink to &quot;本章总结与拓展&quot;">​</a></h2><h3 id="核心概念图谱" tabindex="-1">核心概念图谱 <a class="header-anchor" href="#核心概念图谱" aria-label="Permalink to &quot;核心概念图谱&quot;">​</a></h3><p>建议用PPT呈现一张完整的图谱：</p><ul><li>底层：传感器、PLC（边缘层）</li><li>中层：云平台、大数据、AI（平台层）</li><li>上层：MES、预测性维护（应用层）</li><li>顶端：ERP、供应链（业务层）</li><li>贯穿：安全层</li></ul><h3 id="拓展活动建议" tabindex="-1">拓展活动建议 <a class="header-anchor" href="#拓展活动建议" aria-label="Permalink to &quot;拓展活动建议&quot;">​</a></h3><ol><li><strong>企业调研</strong>：参观当地的智能工厂或数字化车间</li><li><strong>案例分析</strong>：分组查找一个工业互联网应用案例，用IIRA四层分析</li><li><strong>云服务器探索</strong>：在云服务器上尝试安装更多软件（如Node-RED，为第3章做准备）</li></ol><hr><h2 id="参考答案-思考与练习" tabindex="-1">参考答案（思考与练习） <a class="header-anchor" href="#参考答案-思考与练习" aria-label="Permalink to &quot;参考答案（思考与练习）&quot;">​</a></h2><h3 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h3><ol><li><p><strong>你宿舍的无线路由器是工业互联网吗？</strong> 参考答案：不是。逐项对比：连接对象（人vs物）、可靠性要求（偶尔断网没问题vs断网可能出事）、延迟（秒级vs毫秒级）、工作环境（干净舒适vs恶劣）、安全后果（信息泄露vs设备损坏）。</p></li><li><p><strong>数控机床实时监控的IIRA四层设计</strong></p><ul><li>边缘层：传感器+PLC采集数据</li><li>平台层：存储和分析数据</li><li>应用层：办公室看板显示状态</li><li>业务层：设备利用率统计</li></ul></li><li><p><strong>系统集成商项目对接的角色</strong></p><ul><li>设备商：提供PLC、传感器</li><li>平台商：提供PaaS平台</li><li>最终用户：明确需求、付费、使用</li></ul></li><li><p><strong>劳斯莱斯模式为什么需要工业互联网</strong></p><ul><li>没有实时监控就不知道发动机状态，不敢按小时收费，维修成本会吃掉利润</li></ul></li></ol><h3 id="选择题答案" tabindex="-1">选择题答案 <a class="header-anchor" href="#选择题答案" aria-label="Permalink to &quot;选择题答案&quot;">​</a></h3><ol><li>B（通用电气GE）</li><li>C（工业数据量不一定小）</li><li>D（边缘层）</li><li>B（数据闭环）</li><li>B（按飞行小时收费）</li><li>C（三一重工）</li><li>B（以管理员权限执行）</li></ol><h3 id="判断题答案" tabindex="-1">判断题答案 <a class="header-anchor" href="#判断题答案" aria-label="Permalink to &quot;判断题答案&quot;">​</a></h3><ol><li>×（底层逻辑一致）</li><li>√</li><li>×（安全层贯穿其他四层，不是独立并列）</li><li>√</li><li>√</li><li>√</li><li>√</li><li>×（边缘层采集，应用层不直接采集）</li></ol><hr><h2 id="教学反思要点" tabindex="-1">教学反思要点 <a class="header-anchor" href="#教学反思要点" aria-label="Permalink to &quot;教学反思要点&quot;">​</a></h2><p>课后请思考并记录：</p><ol><li>学生对Linux命令的接受度如何？哪些命令掌握最好，哪些最难？</li><li>工业场景的案例是否让学生觉得贴近实际？</li><li>云服务器实践环节有多少学生成功完成？困难主要在哪？</li><li>数据闭环的概念学生是否真正理解了？有什么更好的教学方式？</li><li>思政融入是否自然？有没有更好的切入点？</li></ol>',118)])])}const g=l(o,[["render",d]]);export{b as __pageData,g as default};
